// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./CasinoGameBaseV6.sol";

/**
 * @title ElGatesEngineV7 — "hot" math (v2)
 * @notice Same algorithm as ElGatesEngineV6 with the v2 constants of gatesEngine.ts (MATH_V2):
 *         orbs land ~1.6× as often (base weight 150, free 440) with a heavier tail (100×+ orb
 *         every ~280 spins, 500× every ~2.7k) and symbol pays ×0.578 so the raw engine stays at
 *         ≈98% (base 98.1 · ante 97.7 · buy at 100x 97.0 at the 5000× cap). BIT-FOR-BIT mirror of
 *         playRoundSeed(seed, mode, cap, MATH_V2). Gas layout as V6: the 6×5 grid lives in ONE stack word (8 bits per cell: symbol in
 *         the low nibble, orb-value index in the high nibble), counters are packed words, and
 *         the RNG hashes in scratch space. The V4 engine allocated fresh memory arrays on every
 *         spin/tumble/column, and quadratic memory expansion dominated reveal gas.
 *
 * RNG stream: draw i = 64-bit chunk (i % 4) of keccak256(seed ‖ uint32(i / 4)), lowest first.
 * Cells: index = col*5 + row (row 0 = top). Symbols 0-8 pay (8+ anywhere), 9 = scatter,
 * 10 = multiplier orb. Pays are in bp of the bet (1e4 = 1×).
 */
library ElGatesEngineV7 {
    uint256 internal constant BP = 10000;
    uint256 internal constant MAX_WIN_X = 5000;
    uint256 internal constant FREE_SPINS = 15;
    uint256 internal constant RETRIGGER = 5;
    uint256 internal constant MAX_FREE = 60;
    uint256 internal constant MAX_TUMBLES = 50;
    uint256 internal constant SCATTER = 9;
    uint256 internal constant ORB = 10;
    uint8 internal constant MODE_BASE = 0;
    uint8 internal constant MODE_ANTE = 1;
    uint8 internal constant MODE_BUY = 2;

    struct Rng { bytes32 seed; uint256 i; uint256 word; }

    function _mod(Rng memory r, uint256 n) private pure returns (uint256) {
        uint256 i = r.i;
        uint256 k = i & 3;
        uint256 w;
        if (k == 0) {
            bytes32 s = r.seed;
            assembly ("memory-safe") {
                mstore(0x00, s)
                mstore(0x20, shl(224, shr(2, i)))
                w := keccak256(0x00, 0x24)
            }
            r.word = w;
        } else {
            w = r.word;
        }
        unchecked { r.i = i + 1; }
        return ((w >> (64 * k)) & 0xFFFFFFFFFFFFFFFF) % n;
    }

    /// @dev One fresh cell: symbol | orbIndex << 4. sw/ow = scatter/orb weights for this reel set.
    function _draw(Rng memory r, uint256 sw, uint256 ow) private pure returns (uint256) {
        uint256 x = _mod(r, 17200 + sw + ow);
        if (x < 17200) {
            if (x < 3000) return 0;
            if (x < 5800) return 1;
            if (x < 8400) return 2;
            if (x < 10800) return 3;
            if (x < 12800) return 4;
            if (x < 14200) return 5;
            if (x < 15400) return 6;
            if (x < 16400) return 7;
            return 8;
        }
        if (x < 17200 + sw) return SCATTER;
        uint256 y = _mod(r, 14213);
        uint256 k;
        if (y < 3000) k = 0;
        else if (y < 5400) k = 1;
        else if (y < 7300) k = 2;
        else if (y < 8900) k = 3;
        else if (y < 10100) k = 4;
        else if (y < 11100) k = 5;
        else if (y < 12000) k = 6;
        else if (y < 12600) k = 7;
        else if (y < 13100) k = 8;
        else if (y < 13520) k = 9;
        else if (y < 13840) k = 10;
        else if (y < 14040) k = 11;
        else if (y < 14150) k = 12;
        else if (y < 14195) k = 13;
        else k = 14;
        return ORB | (k << 4);
    }

    function _orbVal(uint256 k) private pure returns (uint256) {
        if (k < 5) return k + 2;                       // 2,3,4,5,6
        if (k == 5) return 8; if (k == 6) return 10; if (k == 7) return 12; if (k == 8) return 15;
        if (k == 9) return 20; if (k == 10) return 25; if (k == 11) return 50; if (k == 12) return 100;
        if (k == 13) return 250; return 500;
    }

    /// @dev Pay (bp of bet) for `n` of symbol `s`.
    function _pay(uint256 s, uint256 n) private pure returns (uint256) {
        if (n < 8) return 0;
        uint256 t = n >= 12 ? 2 : n >= 10 ? 1 : 0;
        if (s == 0) return t == 0 ? 1627 : t == 1 ? 4881 : 13017;
        if (s == 1) return t == 0 ? 2603 : t == 1 ? 5857 : 26033;
        if (s == 2) return t == 0 ? 3254 : t == 1 ? 6508 : 32541;
        if (s == 3) return t == 0 ? 5207 : t == 1 ? 7810 : 52066;
        if (s == 4) return t == 0 ? 6508 : t == 1 ? 9762 : 65083;
        if (s == 5) return t == 0 ? 9762 : t == 1 ? 13017 : 78099;
        if (s == 6) return t == 0 ? 13017 : t == 1 ? 32541 : 97624;
        if (s == 7) return t == 0 ? 16271 : t == 1 ? 65083 : 162707;
        return t == 0 ? 65083 : t == 1 ? 162707 : 325414;
    }

    function _scatterBP(uint256 sc) private pure returns (uint256) {
        return sc >= 6 ? 1_000_000 : sc == 5 ? 50000 : sc == 4 ? 30000 : 0;
    }

    function _spin(Rng memory r, bool free_, bool ante, uint256 force)
        private pure returns (uint256 tumbleBP, uint256 orbSum, uint256 scatters)
    {
        unchecked {
            uint256 sw = free_ ? 210 : (ante ? 375 : 300);
            uint256 ow = free_ ? 440 : 150;
            uint256 g;
            for (uint256 i = 0; i < 30; ++i) g |= _draw(r, sw, ow) << (i * 8);
            uint256 placed;
            while (placed < force) {
                uint256 k = _mod(r, 30);
                if ((g >> (k * 8)) & 0x0F == SCATTER) continue;
                g = (g & ~(uint256(0xFF) << (k * 8))) | (SCATTER << (k * 8));
                placed++;
            }
            for (uint256 t = 0; t < MAX_TUMBLES; ++t) {
                uint256 cnt; // 9 × 8-bit counters
                for (uint256 i = 0; i < 30; ++i) {
                    uint256 s = (g >> (i * 8)) & 0x0F;
                    if (s < 9) cnt += uint256(1) << (s * 8);
                }
                uint256 stepBP; uint256 winMask;
                for (uint256 s = 0; s < 9; ++s) {
                    uint256 p = _pay(s, (cnt >> (s * 8)) & 0xFF);
                    if (p > 0) { stepBP += p; winMask |= uint256(1) << s; }
                }
                if (stepBP == 0) break;
                tumbleBP += stepBP;
                // gravity: survivors keep order and sink; fresh cells fill from the top, column by column
                uint256 ng;
                for (uint256 c = 0; c < 6; ++c) {
                    uint256 keep; uint256 n;
                    for (uint256 row = 0; row < 5; ++row) {
                        uint256 cell = (g >> ((c * 5 + row) * 8)) & 0xFF;
                        uint256 s = cell & 0x0F;
                        if (!(s < 9 && (winMask >> s) & 1 == 1)) { keep |= cell << (n * 8); n++; }
                    }
                    uint256 fresh = 5 - n;
                    for (uint256 row = 0; row < fresh; ++row) ng |= _draw(r, sw, ow) << ((c * 5 + row) * 8);
                    for (uint256 j = 0; j < n; ++j) ng |= ((keep >> (j * 8)) & 0xFF) << ((c * 5 + fresh + j) * 8);
                }
                g = ng;
            }
            for (uint256 i = 0; i < 30; ++i) {
                uint256 cell = (g >> (i * 8)) & 0xFF;
                uint256 s = cell & 0x0F;
                if (s == ORB) orbSum += _orbVal(cell >> 4);
                else if (s == SCATTER) scatters++;
            }
        }
    }

    /// @return totalBP round win in bp of bet, capped at maxWinX × 1e4
    /// @return freeSpins free spins played
    function play(bytes32 seed, uint8 mode, uint256 maxWinX) internal pure returns (uint256 totalBP, uint256 freeSpins) {
        uint256 cap = (maxWinX < MAX_WIN_X ? maxWinX : MAX_WIN_X) * BP;
        Rng memory r = Rng(seed, 0, 0);
        uint256 force = mode == MODE_BUY ? 4 + (_mod(r, 100) < 12 ? 1 : 0) : 0;
        (uint256 tb, uint256 os, uint256 sc) = _spin(r, false, mode == MODE_ANTE, force);
        uint256 total = tb * (tb > 0 && os > 0 ? os : 1) + _scatterBP(sc);
        if (sc >= 4 && total < cap) {
            uint256 left = FREE_SPINS; uint256 mult;
            while (left > 0 && freeSpins < MAX_FREE && total < cap) {
                left--;
                (tb, os, sc) = _spin(r, true, false, 0);
                if (tb > 0 && os > 0) mult += os;
                total += tb * (tb > 0 && mult > 0 ? mult : 1) + _scatterBP(sc);
                if (sc >= 3) left += RETRIGGER;
                freeSpins++;
            }
        }
        totalBP = total < cap ? total : cap;
    }
}

/**
 * @title ElGatesGameV7 — ELGATES (math v2) on the V6 base. Identical to ElGatesGameV6 except the
 *        engine constants; mathVersion() = 2 tells the app which engine replays its rounds.
 *
 * House protections:
 *  - RTP cap 99% (rtpCap). Raw engine EV ≈ 0.98 and the pool keeps 98% of every stake
 *    (1% platform + 1% creator), so even at the cap players get ~97% and stakers keep ~+1%.
 *    The creator picks anything up to that at create time or later via updateConfig.
 *  - Limit caps: maxWin ≤ 25% / maxBet ≤ 5% of available liquidity regardless of config.
 *  - Worst case (bet × maxWinX × rtp) is reserved at commit; payout ≤ reserve by construction.
 *  - Outcome from a FUTURE L2 block hash; reveal is permissionless and pays the round's player;
 *    rounds past the hash window are closed automatically (stake stays with the house).
 */
contract ElGatesGameV7 is CasinoGameBaseV6 {
    uint256 public constant RTP_CAP_BP = 9900;
    uint256 public constant MAX_WIN_BP_CAP = 2500;
    uint256 public constant MAX_BET_RATIO_CAP = 500;
    uint256 public constant BUY_PRICE_MIN = 100;
    uint256 public constant BUY_PRICE_MAX = 250;
    uint256 public constant ANTE_PCT = 125;

    uint256 public immutable maxWinX;
    bool public immutable anteEnabled;
    bool public immutable buyEnabled;
    uint256 public immutable buyPriceX;

    struct Round {
        address player; uint48 commitBlock; uint16 rtpBP; uint8 mode; bool settled; uint16 freeSpins;
        uint112 bet; uint112 stake; uint32 rawBP;
        uint128 maxPayout; uint128 payout;
    }
    mapping(uint256 => Round) internal _rounds;
    uint256 public totalRounds;

    event RoundCommitted(uint256 indexed id, address indexed player, uint8 mode, uint256 bet, uint256 stake);
    event RoundSettled(uint256 indexed id, address indexed player, bytes32 seed, uint8 mode, uint256 rawBP, uint256 payout, uint16 freeSpins);
    event RoundForfeited(uint256 indexed id, address indexed player);

    struct Params { uint256 maxWinX; bool anteEnabled; bool buyEnabled; uint256 buyPriceX; }

    constructor(InitArgs memory a, Params memory p) CasinoGameBaseV6(a) {
        if (a.maxWinBP > MAX_WIN_BP_CAP || a.maxBetRatio > MAX_BET_RATIO_CAP) revert BadConfig();
        if (!(p.maxWinX == 500 || p.maxWinX == 1000 || p.maxWinX == 2500 || p.maxWinX == 5000)) revert BadConfig();
        if (p.buyEnabled && (p.buyPriceX < BUY_PRICE_MIN || p.buyPriceX > BUY_PRICE_MAX)) revert BadConfig();
        maxWinX = p.maxWinX; anteEnabled = p.anteEnabled; buyEnabled = p.buyEnabled; buyPriceX = p.buyPriceX;
    }

    function _betCount() internal view override returns (uint256) { return totalRounds; }
    function rtpCap() public pure override returns (uint256) { return RTP_CAP_BP; }
    function effectiveRtp() public view returns (uint256) { return config.rtpBP; }
    /// @notice Engine math version (the app picks the matching replay engine). V4/V6 rooms = 1.
    function mathVersion() external pure returns (uint256) { return 2; }

    function stakeFor(uint256 bet, uint8 mode) public view returns (uint256) {
        if (mode == ElGatesEngineV7.MODE_ANTE) return (bet * ANTE_PCT) / 100;
        if (mode == ElGatesEngineV7.MODE_BUY) return bet * buyPriceX;
        return bet;
    }

    function _caps() private view returns (uint256 ratio, uint256 mwBP) {
        Config memory c = config;
        ratio = c.maxBetPoolRatio < MAX_BET_RATIO_CAP ? c.maxBetPoolRatio : MAX_BET_RATIO_CAP;
        mwBP = c.maxWinBP < MAX_WIN_BP_CAP ? c.maxWinBP : MAX_WIN_BP_CAP;
    }

    /// @notice Largest bet (not stake) accepted right now for `mode` — mirrors every check in commit.
    function maxBet(uint8 mode) external view returns (uint256) {
        uint256 avail = availableLiquidity();
        uint256 costBP = mode == ElGatesEngineV7.MODE_ANTE ? ANTE_PCT * 100 : mode == ElGatesEngineV7.MODE_BUY ? buyPriceX * BP : BP;
        uint256 payBP = maxWinX * config.rtpBP; // worst-case payout per bet, in bp
        (uint256 ratio, uint256 mwBP) = _caps();
        uint256 byRatio = (avail * ratio) / costBP;
        uint256 byWin = payBP > costBP ? (avail * mwBP) / (payBP - costBP) : type(uint256).max;
        uint256 bySolv = (avail * BP) / payBP;
        uint256 m = byRatio < byWin ? byRatio : byWin;
        return m < bySolv ? m : bySolv;
    }

    function commit(uint256 bet, uint8 mode) external nonReentrant whenNotPaused returns (uint256 id) {
        if (mode > ElGatesEngineV7.MODE_BUY) revert BadInput();
        if (mode == ElGatesEngineV7.MODE_ANTE && !anteEnabled) revert BadInput();
        if (mode == ElGatesEngineV7.MODE_BUY && !buyEnabled) revert BadInput();
        if (bet == 0 || bet < config.minBet) revert BelowMinBet();
        uint256 nowB = _beginBet();
        uint256 stake = stakeFor(bet, mode);
        uint16 rtp = config.rtpBP;
        uint256 maxPayout = (bet * maxWinX * rtp) / BP;
        // protocol caps — hold even if the owner loosened config
        uint256 avail = availableLiquidity();
        (uint256 ratio, uint256 mwBP) = _caps();
        if (stake > (avail * ratio) / BP) revert BetExceedsMax();
        if (maxPayout > (avail * mwBP) / BP + stake) revert WinExceedsMax();
        _openBet(stake, maxPayout);
        _pullAndFee(stake);
        id = totalRounds++;
        _rounds[id] = Round(msg.sender, uint48(nowB), rtp, mode, false, 0, uint112(bet), uint112(stake), 0, uint128(maxPayout), 0);
        _recordBet(msg.sender, id);
        emit RoundCommitted(id, msg.sender, mode, bet, stake);
    }

    /// @notice Permissionless: anyone may settle; the payout always goes to the round's player.
    function reveal(uint256 id) external nonReentrant returns (uint256 payout) {
        Round storage r = _rounds[id];
        if (r.player == address(0)) revert NotFound();
        if (r.settled) revert AlreadySettled();
        bytes32 seed = _seed(r.commitBlock, r.player, id);
        (uint256 rawBP, uint256 fs) = ElGatesEngineV7.play(seed, r.mode, maxWinX);
        payout = (uint256(r.bet) * rawBP * r.rtpBP) / (BP * BP);
        r.settled = true; r.rawBP = uint32(rawBP); r.payout = uint128(payout); r.freeSpins = uint16(fs);
        _closeBet(r.player, r.maxPayout, payout);
        emit RoundSettled(id, r.player, seed, r.mode, rawBP, payout, uint16(fs));
    }

    function forfeit(uint256 id) external nonReentrant {
        Round storage r = _rounds[id];
        if (r.player == address(0)) revert NotFound();
        if (r.settled) revert AlreadySettled();
        if (!_expireBet(id, _l2())) revert TooEarly();
    }

    function _expireBet(uint256 id, uint256 nowB) internal override returns (bool) {
        Round storage r = _rounds[id];
        if (r.settled) return true;
        if (!_isExpired(r.commitBlock, nowB)) return false;
        r.settled = true;
        _closeBet(r.player, r.maxPayout, 0);
        _countExpired();
        emit RoundForfeited(id, r.player);
        return true;
    }

    /// @notice Replay any seed (the UI and auditors use this to verify a settled round).
    function previewRound(bytes32 seed, uint8 mode) external view returns (uint256 rawBP, uint256 freeSpins) {
        return ElGatesEngineV7.play(seed, mode, maxWinX);
    }

    /// @notice V4-shaped view. `seed` is in the RoundSettled event (not stored).
    function rounds(uint256 id) external view returns (
        address player, uint8 mode, bool settled, uint16 freeSpins,
        uint256 bet, uint256 stake, uint256 maxPayout, uint256 rtpBP, uint256 commitBlock,
        uint256 rawBP, uint256 payout, bytes32 seed
    ) {
        Round storage r = _rounds[id];
        return (r.player, r.mode, r.settled, r.freeSpins, r.bet, r.stake, r.maxPayout, r.rtpBP, r.commitBlock, r.rawBP, r.payout, bytes32(0));
    }
    function userRounds(address u, uint256 i) external view returns (uint256) { return _userBetAt(u, i); }
    function getUserRoundCount(address u) external view returns (uint256) { return _userBetCount(u); }
}
